mapper.select:
SELECT * FROM ( SELECT B.BOARD_NO, B.BOARD_TITLE, B.READ_COUNT, B.BOARD_DEL_FL, TO_CHAR(B.CREATED_AT, 'YYYY-MM-DD') AS CREATED_AT, M.NICKNAME AS MEMBER_NICKNAME, ROW_NUMBER() OVER (ORDER BY B.BOARD_NO DESC) AS RN FROM BOARD B JOIN MEMBER M ON B.MEMBER_NO = M.MEMBER_NO JOIN BOARD_TYPE BT ON B.BOARD_TYPE_NO = BT.BOARD_TYPE_NO WHERE BT.BOARD_TYPE_CODE = 'NOTICE' AND B.BOARD_DEL_FL = 'N'
AND B.BOARD_TITLE LIKE '%' || #{search} || '%'
) WHERE RN BETWEEN #{offset} + 1 AND #{offset} + #{limit}

mapper.update:
UPDATE BOARD
SET READ_COUNT = READ_COUNT + 1
WHERE BOARD_NO = #{boardNo}

